function createEpisodes(count, thumb, seasonNum = 1) {
  const eps = [];
  for (let i = 1; i <= count; i++) {
    eps.push({
      id: i,
      number: i,
      season: seasonNum,
      title: `Episode ${i}`,
      runtime: "24m",
      thumbnail: thumb,
      synopsis: `Episode ${i}`,
      videoUrl: SAMPLE_VIDEOS[0]
    });
  }
  return eps;
}

